1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Normalises the string fields used by the owner duplicate checks so that comparisons ignore
7	 * letter case and surrounding or repeated whitespace. For example {@code "  john   smith "} and
8	 * {@code "John Smith"} normalise to the same key and therefore count as the same person.
9	 */
10	final class DuplicateKey {
11	
12	    private DuplicateKey() {
13	    }
14	
15	    /**
16	     * Returns a comparison key for the given value: leading/trailing whitespace removed, any run
17	     * of internal whitespace collapsed to a single space, and letters lower-cased. Returns
18	     * {@code null} when the value is {@code null} so callers can treat "no value" distinctly.
19	     */
20	    static String normalize(String value) {
21	        if (value == null) {
